#!/bin/sh
set -e
goal="Move postcss.config.js to src/frontend and configure vite to use it."
echo "Plan:"
echo "1. Move the postcss.config.cjs to src/frontend/postcss.config.cjs"
echo "2. Update the vite.config.js to use the new postcss config location."

# Moving postcss.config.cjs to src/frontend/
mv postcss.config.cjs src/frontend/postcss.config.cjs

# Update the vite.config.js
cat << 'EOF' > src/vite.config.js
import { defineConfig } from 'vite'
import solidPlugin from 'vite-plugin-solid'

export default defineConfig({
  plugins: [solidPlugin()],
  css: {
    postcss: './src/frontend/postcss.config.cjs'
  },
  build: {
    target: 'esnext',
  },
})
EOF

echo "\033[32mDone: $goal\033[0m\n"

